8	/**
9	 * Assigns, on the owner being created, the membership points and the numeric membership level derived
10	 * from them. Points start at zero and gain: 2 when an email is present, 1 when the owner has no
11	 * pre-existing namesakes ({@code namesakeCount} of zero), 2 for a household of three or more, and 3 for
12	 * a tenure of more than one elapsed fiscal year (1 July basis) measured from the owner's
13	 * {@code registrationDate}. The points map to a
14	 * level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. Runs after
15	 * {@link NormalizeOwnerEmail}, {@link AssignNamesakeCount} and {@link AssignHouseholdSize} so all inputs
16	 * are settled, and before {@link SaveOwner} persists the values.
17	 */
18	public class AssignMembershipLevel {
19	
20	    /** A tenure of strictly more than this many elapsed fiscal years scores the tenure points. */
21	    private static final long TENURE_POINTS_FISCAL_YEARS = 1;
22	
23	    public void service(@Val Owner owner) {
24	        int points = 0;
25	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
26	            points += 2;
27	        }
28	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
29	            points += 1;
30	        }
31	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
32	            points += 2;
33	        }
34	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
35	            points += 3;
36	        }
37	        owner.setMembershipPoints(points);
38	        owner.setMembershipLevel(levelOf(points));
39	    }
40	
41	    private static int levelOf(int points) {
42	        if (points <= 1) {
43	            return 1;
44	        }
45	        if (points <= 3) {
46	            return 2;
47	        }
48	        if (points <= 5) {
49	            return 3;
50	        }
51	        return 4;
52	    }
53	
54	    private static long tenureFiscalYears(Owner owner) {
55	        LocalDate registrationDate = owner.getRegistrationDate();
56	        if (registrationDate == null) {
57	            return 0;
58	        }
59	        return FiscalYear.elapsedBetween(registrationDate, LocalDate.now());
60	    }
61	}
