8	 * Caps, on the owner being created, its {@code membershipLevel} so it cannot exceed one above the
9	 * current maximum {@code membershipLevel} among the existing members of its household — the owners
10	 * already saved that share the same deterministic {@code householdId} (see {@link HouseholdId}).
11	 * With no existing household member no cap applies and the level assigned by
12	 * {@link AssignMembershipLevel} stands.
13	 *
14	 * <p>Runs after {@link AssignMembershipLevel}, which has set the raw level, and before
15	 * {@link SaveOwner} persists it.
16	 */
17	public class CapMembershipLevel {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        Integer level = owner.getMembershipLevel();
21	        if (level == null) {
22	            return;
23	        }
24	        String householdId = owner.getHouseholdId();
25	        Integer maxExisting = null;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (householdId.equals(HouseholdId.of(existing))
28	                    && existing.getMembershipLevel() != null
29	                    && (maxExisting == null || existing.getMembershipLevel() > maxExisting)) {
30	                maxExisting = existing.getMembershipLevel();
31	            }
32	        }
33	        if (maxExisting != null && level > maxExisting + 1) {
34	            owner.setMembershipLevel(maxExisting + 1);
35	        }
36	    }
37	}
